from ..entities.k8s_executor import K8sExecutor
from ..templates.dynamic_class_creation import Creating
from .factory import Factory
from .named_factory import NamedComponentFactory


class K8sExecutorFactoryBase(Factory):
    _mandatory_parameters = {"namespace"}
    _optional_parameters = {"pod"}
    _product_class = K8sExecutor

    def __init__(self, container_default, **kwargs):
        super(K8sExecutorFactoryBase, self).__init__(**kwargs)
        self._container_default = container_default

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(K8sExecutorFactoryBase, self)._build_arguments(configuration, existing_arguments, resulting_arguments)
        resulting_arguments["container"] = configuration.get("container", self._container_default)


class LocalK8sExecutorFactory(Creating("tool_executor", "LocalExecutor"), K8sExecutorFactoryBase):
    pass


class RemoteK8sExecutorFactory(Creating("tool_executor", "SshExecutor", "executor"), K8sExecutorFactoryBase):
    pass


class K8sExecutorFactorySelector(Factory):
    def __init__(self, container_default, **kwargs):
        super(K8sExecutorFactorySelector, self).__init__(**kwargs)
        self._container_default = container_default

    def create(self, configuration, existing_arguments):
        if "executor" in configuration:
            return RemoteK8sExecutorFactory(
                container_default=self._container_default).create(
                    configuration=configuration,
                    existing_arguments=existing_arguments)
        else:
            return LocalK8sExecutorFactory(
                container_default=self._container_default).create(
                configuration=configuration,
                existing_arguments=existing_arguments)


class K8sCommandCollectorFactory(NamedComponentFactory):
    def __int__(self, **kwargs):
        super(K8sCommandCollectorFactory, self).__init__(**kwargs)
        self._container_default = None  # set this attribute in constructor of derived class

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(K8sCommandCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["tool_executor"] = K8sExecutorFactorySelector(
            container_default=self._container_default).create(
                configuration=configuration,
                existing_arguments=existing_arguments)
